#!/bin/sh
# Tinty hook: generate dunst colours from base24 palette

hex() {
  eval "printf '#%s%s%s' \"\$TINTY_SCHEME_PALETTE_BASE${1}_HEX_R\" \"\$TINTY_SCHEME_PALETTE_BASE${1}_HEX_G\" \"\$TINTY_SCHEME_PALETTE_BASE${1}_HEX_B\""
}

OUT="$HOME/.config/dunst/dunstrc.d/10-tinted.conf"
mkdir -p "$(dirname "$OUT")"

cat > "$OUT" << CONF
# Auto-generated by tinty — do not edit
[urgency_low]
    background = "$(hex 00)f0"
    foreground = "$(hex 04)"
    frame_color = "$(hex 03)73"
    highlight = "$(hex 0D)"
    timeout = 5

[urgency_normal]
    background = "$(hex 00)f0"
    foreground = "$(hex 05)"
    frame_color = "$(hex 03)73"
    highlight = "$(hex 0D)"
    timeout = 8

[urgency_critical]
    background = "$(hex 00)f0"
    foreground = "$(hex 05)"
    frame_color = "$(hex 08)"
    highlight = "$(hex 08)"
    timeout = 0
CONF

command -v dunstctl >/dev/null && dunstctl reload >/dev/null 2>&1
exit 0
